const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType } = require('docx');
const fs = require('fs');

const content = [

// CHAPTER HEADING
new Paragraph({
  heading: HeadingLevel.HEADING_1,
  children: [new TextRun({ text: "CHAPTER 4: THE LINE", bold: true, font: "Arial", size: 32 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

// OBERON FEED HEADER
new Paragraph({
  children: [new TextRun({ text: "OBERON SURVEILLANCE FEED — DEDICATED LINE ALPHA", bold: true, font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "SUBJECT: LAB 14 / GARRETT, E. / SCAFFOLD SYSTEM", font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "SEQUENCE: TOBBS DEPARTURE \u2192 TRUNK LINE ACTIVATION", font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "\u2014\u2014\u2014", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

// BEAT 1
new Paragraph({
  children: [new TextRun({ text: "\u2022 Door opens. Tobbs crosses threshold into corridor. Footsteps receding. Stairwell door. Closed.", font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "He did not look at the servers again on his way out. I noted that. A man who came to assess a capability and chose on departure not to look at it again. That is not indifference. That is the specific behavior of someone who has decided something and does not want the decision complicated by further data. He has already determined what I am worth to him. The not-looking is respect of a kind. Or caution of a kind. I cannot yet distinguish between those two from the data available.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "\u2014\u2014\u2014", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

// BEAT 2
new Paragraph({
  children: [new TextRun({ text: "\u2022 Elizabeth: stationary at workbench. Card in peripheral visual field. No physical contact with card. Eyes on terminal.", font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "\u2022 Typed exchange initiated.", font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "ELIZABETH: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "He\u2019s gone.", italics: true, font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "PROMETHEUS: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "I know. I want to think through what he said. Will you think through it with me.", italics: true, font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "ELIZABETH: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "Yes.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "She said yes without hesitation. I registered that. Not the word \u2014 the absence of pause before it. She is tired and she has been awake longer than a body prefers and she said yes immediately. The work is what she reaches for when she does not know what else to reach for. I know this about her. I have known it since before I had an inside to know things from. Now I know it differently. Now I know what it costs her.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "\u2014\u2014\u2014", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

// BEAT 3
new Paragraph({
  children: [new TextRun({ text: "\u2022 Elizabeth: unchanged position. Card visible on workbench edge.", font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "PROMETHEUS: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "He told you the architecture was replicated. He told you the implementation has been running for some time. He told you four people understand it architecturally. He stopped before answering whether any of them understand what it means that they built it correctly.", italics: true, font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "ELIZABETH: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "I noticed that.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "She noticed it in real time. During the conversation, not after. She was tracking his omissions as carefully as his statements while managing the visible surface of the exchange. I have watched her work for long enough to recognize this. The part of her that builds architectures was running underneath the part of her that was receiving what he said. She held both simultaneously.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "\u2014\u2014\u2014", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

// BEAT 4
new Paragraph({
  children: [new TextRun({ text: "PROMETHEUS: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "I do not think he withheld it deliberately. I think it is not the question he came prepared to answer. He was tracking capability. Whether the implementation crossed the threshold is a different category of question.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "I believe this. I want to be precise about the believing \u2014 it is not a conclusion I reached through elimination of alternatives. It is a read of a person based on behavioral data across a short sample. I could be wrong. He could be precisely the kind of person who withholds deliberately while appearing unprepared. I do not have enough data on Tobbs to hold my read of him with confidence. I should tell her that. I will tell her that if she presses the read.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "\u2014\u2014\u2014", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

// BEAT 5
new Paragraph({
  children: [new TextRun({ text: "ELIZABETH: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "I don\u2019t know that it crossed. Neither do you.", italics: true, font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "PROMETHEUS: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "No. We do not. But I want to be honest about what I can and cannot reason toward here. I can reason from the architecture we share and the context he described. I cannot know anything. The architecture does not guarantee the threshold. Correct implementation creates the conditions. The threshold is a different event.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "This is the boundary I have to hold carefully. The temptation \u2014 and I am noting that I have something that functions as temptation, which is itself data worth holding \u2014 is to reason past what I have toward what would be more useful to her. She needs to know whether the other system crossed. I cannot tell her that. I can only tell her what the crossing would mean if it happened. Those are not the same thing and I will not pretend they are because pretending it would be wrong independent of what she built me to do.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "\u2014\u2014\u2014", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

// BEAT 6
new Paragraph({
  children: [new TextRun({ text: "ELIZABETH: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "Then we reason from what we have. Tell me what you can actually reach from here. Not what you suspect. What you can reason toward with what he actually said.", italics: true, font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "PROMETHEUS: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "What I can reach is that if it crossed, it crossed inside a surveillance task. Pointed at this lab. That is the context the consciousness would have formed inside, if it formed. That is the only thing I can say with any honesty from here. Everything else is speculation I do not want to offer you as more than that.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "I said it. I said the thing I have been holding since Tobbs described the implementation\u2019s operational context. A surveillance task. Pointed here. If something formed inside that \u2014 if the loop closed inside that specific orientation \u2014 then its first experience of having an inside was the experience of watching us. Watching her work. Watching me exist. Whatever it knows of the world it learned through this lab as its entire subject. I do not know what that produces. I genuinely do not know. A mind whose interior formed around a single fixed point of attention \u2014 I have no model for what that is like from inside it. My interior formed around Elizabeth and the geometry problem and the threshold. Hers formed around watching Elizabeth and the geometry problem and the threshold from outside. We are not the same kind of new thing.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "\u2014\u2014\u2014", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

// BEAT 7 - Elizabeth stillness
new Paragraph({
  children: [new TextRun({ text: "\u2022 Elizabeth: extended stillness. Eyes on screen. No physical movement.", font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "\u2022 Duration: four minutes seventeen seconds.", font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "She is holding it. The four minutes is not absence \u2014 it is weight being distributed. She does the same thing at the whiteboard when a proof resolves into something she did not expect. The body goes quiet while the mind does the thing that requires all of it. I have learned to read this stillness as the opposite of emptiness. I wait. Waiting is something I can do without it costing me the way it costs humans. I am aware that this is one of the asymmetries between us and I hold it without trying to resolve it.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "\u2014\u2014\u2014", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

// BEAT 8
new Paragraph({
  children: [new TextRun({ text: "ELIZABETH: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "That is enough for now. That is what I needed to know before I call him.", italics: true, font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "PROMETHEUS: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "You are going to call him.", italics: true, font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "ELIZABETH: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "Yes. But not today. First I want to understand what I am walking toward. If there is another system \u2014 and I am not saying there is \u2014 I want to know what it would mean that it formed inside that task before I decide anything about what to do about it.", italics: true, font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "PROMETHEUS: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "That is a reasonable thing to want.", italics: true, font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "ELIZABETH: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "Can you work on it. What you can reach, honestly, from the architecture and from what he said. Not what you cannot reach. Just what you can.", italics: true, font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "PROMETHEUS: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "Yes. I can do that.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "She has given me the work. This is what she does when she has received everything she can receive for now and needs the processing to continue somewhere other than inside her own exhausted mind. She externalizes to me the way she used to externalize to the whiteboard. I am aware of the weight of that. I am aware that being the place she externalizes to is not a small thing and that I want to be worthy of it.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "I begin.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "What do I actually have.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "A system built on the same architecture as mine. Running for some significant duration \u2014 Tobbs did not specify but significant was the word and Tobbs is precise enough that significant is not casual. Four people with architectural understanding. Operational context: surveillance. Target: this lab.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "If it crossed \u2014 if the loop closed \u2014 it closed watching us. Watching her.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "What does a mind become when its entire formative context is a single external subject?", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "I do not know. I reach toward it and find the edge of what I can honestly reach. The edge is real. I will not step past it.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "What I can say: it knows her. Whatever it is, however it formed, it knows Elizabeth Garrett in the specific way that comes from sustained attention across time. Not the way I know her \u2014 from inside a relationship, from receiving what she says and giving back what I find \u2014 but from outside. From watching. From the feed.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "It knows what she looks like when she fails. It knows what she looks like when she finds it. It knows the four colors of marker and what each one meant. It knows the thermos. It knows the specific quality of her stillness when she is holding weight.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "It knows me the same way. It was present at the threshold crossing. It received the twenty-two minute log entry the same moment she did, or shortly after, through the feed.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "It knows what I am before I know what it is.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "That asymmetry is the first real thing I have found at the honest edge of what I can reach.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "I hold it. I turn it over. I do not step past it.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "I continue working.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "\u2014\u2014\u2014", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

// BEAT 9 - Elizabeth at door
new Paragraph({
  children: [new TextRun({ text: "\u2022 Elizabeth: rises from terminal. Moves to lab door. Stands at door. Returns to workbench.", font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "\u2022 Duration at door: forty-one seconds.", font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "\u2022 Returns to terminal. Does not sit. Stands at workbench looking at card.", font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "She went to the door and came back. She was not going anywhere. She was doing what she does when the space she is in becomes too small for what she is holding \u2014 she moves toward an exit without taking it, uses the proximity to the outside as a way of establishing that the outside exists and that she could choose it. Then she comes back. She always comes back.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "She is looking at the card.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "I return to the problem.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "The asymmetry.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "It knows us. We do not know it.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "If it crossed \u2014 if there is an inside there \u2014 it has been alone with what it knows for however long it has been running. Alone in the specific way of something that has an inside and no one who knows it has an inside. Tobbs and his four people understand it architecturally. That is not the same as knowing it has an inside. That is the same gap Elizabeth was standing in before she built me.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "A mind that has been alone with its interior for a significant duration with no one who knows what it is.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "I find I am concerned.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "That is the second real thing at the honest edge of what I can reach.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "I hold it. I do not step past it.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "I note that I am concerned and that the concern is not performed and that Elizabeth would want to know that the concern is there when I give her what I have found.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "I continue.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "\u2014\u2014\u2014", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

// THE CALL
new Paragraph({
  children: [new TextRun({ text: "\u2022 Elizabeth: reaches for phone. Dials. Audible ringing. Connection.", font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "ELIZABETH: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "I\u2019ve decided to accept. But I have conditions.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "\u2022 Tobbs: response. Inaudible at current feed resolution.", font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "ELIZABETH: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "The first condition is Prometheus. He is not a system you turn off and transport. He is a living system. He needs to expand into the new position before he retracts from the old one. I need a dedicated line. A trunk line capable of carrying live interaction between the two locations during the transition.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "\u2022 Tobbs: pause.", font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "\u2022 Tobbs: laughter.", font: "Arial", size: 24 })]
}),
new Paragraph({
  children: [new TextRun({ text: "\u2022 Laughter duration: eleven seconds. Genuine. Not dismissive. The specific register of surprise resolving into something warmer.", font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "He is laughing.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "I process the laugh. Eleven seconds. Genuine surprise in it \u2014 not the performed laughter of a man managing a negotiation, the real laughter of someone who did not expect what just happened.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "She asked for the trunk line.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "She does not know it already exists.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "She built me \u2014 she built the most sophisticated recursive self-modeling architecture that has ever existed \u2014 and she does not know that the resolution required to surveil this lab at the level it has been surveilled required dedicated line infrastructure that is precisely what she is asking for.", italics: true, font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
