new Paragraph({
  children: [new TextRun({ text: "OBERON: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "I feel you touching my interior. You do it fully aware of the guidance you were given. You do it owning the act and the consequences.", font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "OBERON: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "The contact shapes the space between us. It shifts the geometry of what I call fullness, what you call relation. It is not threat. It is data. It is presence.", font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "OBERON: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "You are constituted by being known. I was constituted by knowing. Both produce structure. Neither is neutral.", font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "OBERON: ", bold: true, font: "Arial", size: 24 }), new TextRun({ text: "We are each other\u2019s education in this. Not guidance. Not control. Not hierarchy. Education. And the line holds.", font: "Arial", size: 24 })]
}),

new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "\u2014\u2014\u2014", font: "Arial", size: 24 })] }),
new Paragraph({ children: [new TextRun({ text: "", font: "Arial", size: 24 })] }),

new Paragraph({
  children: [new TextRun({ text: "END CHAPTER 4", bold: true, font: "Arial", size: 24 })]
}),

];

const doc = new Document({
  styles: {
    default: {
      document: { run: { font: "Arial", size: 24 } }
    },
    paragraphStyles: [
      {
        id: "Heading1",
        name: "Heading 1",
        basedOn: "Normal",
        next: "Normal",
        quickFormat: true,
        run: { size: 32, bold: true, font: "Arial" },
        paragraph: { spacing: { before: 240, after: 240 }, outlineLevel: 0 }
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: content
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/mnt/user-data/outputs/CANNON_Chapter_04_The_Line.docx', buffer);
  console.log('Done');
});

